package com.reqlens.app;
import android.app.*;import android.graphics.Typeface;import android.os.Bundle;import android.widget.*;import java.net.*;import java.util.*;
public final class HostSummaryActivity extends Activity{
 static final class S{int count,errors;long bytes;Map<String,Integer>paths=new HashMap<>();}
 @Override public void onCreate(Bundle b){super.onCreate(b);ProjectRepository.init(this);ProxyHistoryRepository.init(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(16,16,16,16);TextView t=new TextView(this);t.setText("Host / Endpoint Summary");t.setTextSize(22);t.setTypeface(Typeface.DEFAULT_BOLD);r.addView(t);TextView o=new TextView(this);o.setTypeface(Typeface.MONOSPACE);o.setTextIsSelectable(true);o.setText(build());ScrollView s=new ScrollView(this);s.addView(o);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
 private String build(){Map<String,S>m=new TreeMap<>();for(ProxyEvent e:ProxyHistoryRepository.snapshotActiveProject()){String h=e.host.isEmpty()?e.ip:e.host;if(h.isEmpty())continue;S x=m.computeIfAbsent(h,k->new S());x.count++;x.bytes+=Math.max(0,e.bytes);if(e.status>=400||e.status<0)x.errors++;if(!e.url.isEmpty())try{String p=new URL(e.url).getPath();if(p==null||p.isEmpty())p="/";x.paths.merge(p,1,Integer::sum);}catch(Exception ignored){}}StringBuilder s=new StringBuilder();for(Map.Entry<String,S>e:m.entrySet()){s.append(e.getKey()).append("\n  requests: ").append(e.getValue().count).append("  errors: ").append(e.getValue().errors).append("  bytes: ").append(e.getValue().bytes).append("\n");List<Map.Entry<String,Integer>>p=new ArrayList<>(e.getValue().paths.entrySet());p.sort((a,b)->Integer.compare(b.getValue(),a.getValue()));for(int i=0;i<Math.min(10,p.size());i++)s.append("    ").append(p.get(i).getValue()).append("× ").append(p.get(i).getKey()).append('\n');}return s.length()==0?"No hosts yet":s.toString();}
}
